def gcdValues(A: List[int], queries: List[int]) -> List[int]:
    MX = 50001
    divisors = [[] for _ in range(MX)]

    for x in range(1, MX):
        for multiple in range(x, MX, x):
            divisors[multiple].append(x)

    M = max(A) if A else 0
