    for num in A:
        countA[num] = countA.get(num, 0) + 1

    countD = {}
    for x in countA:
        for d in divisors[x]:
            countD[d] = countD.get(d, 0) + countA[x]

    countG = {}
    for g in range(M, 0, -1):
        c = countD.get(g, 0)
        if c > 1:
            countG[g] = c * (c - 1) // 2
        else:
            countG[g] = 0
            for x in range(2*g, M+1, g):
                if x in countG:
                    countG[g] -= countG[x]

    glist = sorted(countG.keys(), reverse=True)
    vlist = [countG[g] for g in glist]
    Pvlist = []
    current_sum = 0
    for val in vlist:
        current_sum += val
        Pvlist.append(current_sum)

    ans = []
